package org.jsoup.nodes;

import java.io.*;
import java.math.*;
import java.util.*;
import java.util.ArrayList;
import java.util.List;
import org.jsoup.Connection;
import org.jsoup.Jsoup;
import org.jsoup.helper.HttpConnection;
import org.jsoup.helper.Validate;
import org.jsoup.nodes.Element;
import org.jsoup.parser.Tag;
import org.jsoup.select.Elements;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;

public class FormElement_formData_TriageGen2Test {

    @Test
    public void testFormData_EmptyElements() {
        FormElement form = new FormElement(Tag.valueOf("form"), "", null);
        List<Connection.KeyVal> result = form.formData();
        assertTrue(result.isEmpty());
    }

    @Test
    public void testFormData_SkipNonSubmittableAndDisabled() {
        FormElement form = new FormElement(Tag.valueOf("form"), "", null);

        // Non-submittable element (e.g., a div)
        Element div = new Element(Tag.valueOf("div"), "", null);
        form.appendChild(div);

        // Submittable but disabled
        Element disabledInput = new Element(Tag.valueOf("input"), "", null);
        disabledInput.attr("name", "disabled_input");
        disabledInput.attr("disabled", "");
        form.appendChild(disabledInput);

        // Submittable but no name
        Element noNameInput = new Element(Tag.valueOf("input"), "", null);
        noNameInput.attr("type", "text");
        form.appendChild(noNameInput);

        List<Connection.KeyVal> result = form.formData();
        assertTrue(result.isEmpty());
    }

    @Test
    public void testFormData_TextInputs() {
        FormElement form = new FormElement(Tag.valueOf("form"), "", null);
        Element input = new Element(Tag.valueOf("input"), "", null);
        input.attr("name", "username");
        input.attr("type", "text");
        input.attr("value", "john_doe");
        form.appendChild(input);

        List<Connection.KeyVal> result = form.formData();
        assertEquals(1, result.size());
        assertEquals("username", result.get(0).getKey());
        assertEquals("john_doe", result.get(0).getValue());
    }

    @Test
    public void testFormData_SelectWithSelectedOption() {
        FormElement form = new FormElement(Tag.valueOf("form"), "", null);
        Element select = new Element(Tag.valueOf("select"), "", null);
        select.attr("name", "choice");

        Element opt1 = new Element(Tag.valueOf("option"), "", null);
        opt1.attr("value", "1");
        opt1.text("One");

        Element opt2 = new Element(Tag.valueOf("option"), "", null);
        opt2.attr("value", "2");
        opt2.attr("selected", "");
        opt2.text("Two");

        select.appendChild(opt1);
        select.appendChild(opt2);
        form.appendChild(select);

        List<Connection.KeyVal> result = form.formData();
        assertEquals(1, result.size());
        assertEquals("choice", result.get(0).getKey());
        assertEquals("2", result.get(0).getValue());
    }

    @Test
    public void testFormData_SelectMultipleSelectedOptions() {
        FormElement form = new FormElement(Tag.valueOf("form"), "", null);
        Element select = new Element(Tag.valueOf("select"), "", null);
        select.attr("name", "choices");

        Element opt1 = new Element(Tag.valueOf("option"), "", null);
        opt1.attr("value", "A");
        opt1.attr("selected", "");

        Element opt2 = new Element(Tag.valueOf("option"), "", null);
        opt2.attr("value", "B");
        opt2.attr("selected", "");

        select.appendChild(opt1);
        select.appendChild(opt2);
        form.appendChild(select);

        List<Connection.KeyVal> result = form.formData();
        assertEquals(2, result.size());
        assertEquals("A", result.get(0).getValue());
        assertEquals("B", result.get(1).getValue());
    }

    @Test
    public void testFormData_SelectWithNoSelectedOption() {
        FormElement form = new FormElement(Tag.valueOf("form"), "", null);
        Element select = new Element(Tag.valueOf("select"), "", null);
        select.attr("name", "choice");

        Element opt1 = new Element(Tag.valueOf("option"), "", null);
        opt1.attr("value", "first");

        Element opt2 = new Element(Tag.valueOf("option"), "", null);
        opt2.attr("value", "second");

        select.appendChild(opt1);
        select.appendChild(opt2);
        form.appendChild(select);

        List<Connection.KeyVal> result = form.formData();
        assertEquals(1, result.size());
        assertEquals("first", result.get(0).getValue());
    }

    @Test
    public void testFormData_SelectWithNoOptions() {
        FormElement form = new FormElement(Tag.valueOf("form"), "", null);
        Element select = new Element(Tag.valueOf("select"), "", null);
        select.attr("name", "empty_select");
        form.appendChild(select);

        List<Connection.KeyVal> result = form.formData();
        assertTrue(result.isEmpty());
    }

    @Test
    public void testFormData_CheckboxAndRadio() {
        FormElement form = new FormElement(Tag.valueOf("form"), "", null);

        // Checked checkbox with value
        Element cb1 = new Element(Tag.valueOf("input"), "", null);
        cb1.attr("name", "cb1");
        cb1.attr("type", "checkbox");
        cb1.attr("checked", "");
        cb1.attr("value", "yes");
        form.appendChild(cb1);

        // Checked checkbox without value (should be "on")
        Element cb2 = new Element(Tag.valueOf("input"), "", null);
        cb2.attr("name", "cb2");
        cb2.attr("type", "checkbox");
        cb2.attr("checked", "");
        form.appendChild(cb2);

        // Unchecked checkbox
        Element cb3 = new Element(Tag.valueOf("input"), "", null);
        cb3.attr("name", "cb3");
        cb3.attr("type", "checkbox");
        form.appendChild(cb3);

        // Checked radio
        Element rb1 = new Element(Tag.valueOf("input"), "", null);
        rb1.attr("name", "rb1");
        rb1.attr("type", "radio");
        rb1.attr("checked", "");
        rb1.attr("value", "option1");
        form.appendChild(rb1);

        List<Connection.KeyVal> result = form.formData();
        assertEquals(3, result.size());

        assertEquals("cb1", result.get(0).getKey());
        assertEquals("yes", result.get(0).getValue());

        assertEquals("cb2", result.get(1).getKey());
        assertEquals("on", result.get(1).getValue());

        assertEquals("rb1", result.get(2).getKey());
        assertEquals("option1", result.get(2).getValue());
    }
}
